def link_existing_competitions(apps, schema_editor):
    """Competitions that already have a winning project get that project as their project_id."""
    Competition = apps.get_model("api", "Competition")
    CompetitionAward = apps.get_model("api", "CompetitionAward")
    for competition in Competition.objects.filter(project__isnull=True):
        award = CompetitionAward.objects.filter(competition=competition).order_by("sorting_order", "id").first()
